using int64 = long long;

bool good(int64 A, int64 B, int64 x, int64 y, int64 v) {
    if (v <= 1 || x <= 0 || y <= 0) {
        return false;
    }

    int64 delX = v / x;
    int64 delY = v / y;

    __int128 product = static_cast<__int128>(x) * y;
    int64 delXY = product > v ? 0 : v / static_cast<int64>(product);

    int64 fa = v - delX;
    int64 fb = v - delY;
    int64 fab = v - (delX + delY - delXY);

    int64 onlyA = fa - fab;
    int64 onlyB = fb - fab;

    A = max<int64>(0, A - onlyA);
    B = max<int64>(0, B - onlyB);

    return A + B <= fab;
}

int64 bsearch(int64 A, int64 B, int64 x, int64 y,
              int64 left, int64 right) {
    int64 answer = -1;

    while (left <= right) {
        int64 middle = left + (right - left) / 2;

        if (good(A, B, x, y, middle)) {
            answer = middle;
            right = middle - 1;
        } else {
            left = middle + 1;
        }
    }

    return answer;
}

