int bsearch(int A, int B, int x, int y, int left, int right){
	if(right - left < 10){
		for(int i = left; i<=right; i++){
			int g = good(A, B, x, y, i);
			if(g){
				return i;
			}
		}
	}

	int middle = (left+right)/2;
	int g = good(A, B, x, y, middle);
	if(g){
		return bsearch(A, B, x, y, left, middle);
	}
	else{
		return bsearch(A, B, x, y, middle+1, right);
	}
}

